test("時計が進むと経過時間も進む", () => {
  const clock = createClockFake(StartEpochMs + 4000);
  render(
    <ElapsedHarness
      clock={clock.clock}
      initialSince={Option.some(Instant.create(StartEpochMs))}
    />,
  );

  act(() => {
    clock.advanceSeconds(1);
  });

  expect(elapsedText()).toBe("5:seconds");
});
